package com.portfolio.shopsphere.controller;import com.portfolio.shopsphere.model.Product;import com.portfolio.shopsphere.repo.ProductRepository;import jakarta.validation.Valid;import org.springframework.http.*;import org.springframework.web.bind.annotation.*;import java.util.*;@RestController @RequestMapping("/api/products") @CrossOrigin(origins="http://localhost:5173")public class ProductController{final ProductRepository r;ProductController(ProductRepository r){this.r=r;}@GetMapping List<Product>all(@RequestParam(defaultValue="")String q){return q.isBlank()?r.findAll():r.findByNameContainingIgnoreCaseOrCategoryContainingIgnoreCase(q,q);}@PostMapping ResponseEntity<Product>create(@Valid @RequestBody Product p){return ResponseEntity.status(HttpStatus.CREATED).body(r.save(p));}@PutMapping("/{id}")ResponseEntity<Product>update(@PathVariable Long id,@Valid @RequestBody Product p){return r.findById(id).map(x->{p.id=x.id;return ResponseEntity.ok(r.save(p));}).orElse(ResponseEntity.notFound().build());}@DeleteMapping("/{id}")void delete(@PathVariable Long id){r.deleteById(id);}}
